import { classificationRegistry } from "../classification/registry.js";
import { DataClass, lawfulBasisForPurpose, type Purpose } from "../classification/vocabulary.js";

const GENERATED_NOTE =
  "<!-- Generated by `pnpm compliance:generate`. Do not edit. CI fails if this is stale. -->";

const PERSONAL_CLASSES = new Set<string>([DataClass.Pii, DataClass.Phi, DataClass.Pseudonymous]);

interface PurposeRow {
  readonly categories: Set<string>;
  readonly retentions: Set<string>;
  readonly tables: Set<string>;
}

/**
 * The GDPR Article 30 record of processing, grouped by purpose.
 *
 * Only columns holding personal data appear. Operational and secret columns are
 * excluded: Art.30 is about processing personal data, and padding it with counters
 * makes it harder for an auditor to read, not more complete.
 */
export function generateRopa(): string {
  const byPurpose = new Map<Purpose, PurposeRow>();

  for (const [table, columns] of classificationRegistry()) {
    for (const [column, c] of Object.entries(columns)) {
      if (!PERSONAL_CLASSES.has(c.class)) continue;
      const row = byPurpose.get(c.purpose) ?? {
        categories: new Set<string>(),
        retentions: new Set<string>(),
        tables: new Set<string>(),
      };
      row.categories.add(`${c.class}: ${column}`);
      row.retentions.add(c.retention);
      row.tables.add(table);
      byPurpose.set(c.purpose, row);
    }
  }

  const lines: string[] = [
    GENERATED_NOTE,
    "",
    "# Record of processing activities (GDPR Article 30)",
    "",
    "Generated from the schema classification (PROJECT.md 4.13.2).",
    "",
    "Role: Idenzy is a **processor** for end-user data held on behalf of a customer, and a",
    "**controller** for the customer's own account data. Data is pinned to a region cell at",
    "project creation and does not leave it (PROJECT.md 4.13.5).",
    "",
    "This document is generated architecture, not a compliance attestation. Idenzy holds no",
    "certification; see PROJECT.md 4.13.10.",
    "",
  ];

  for (const [purpose, row] of [...byPurpose.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    lines.push(
      `## ${purpose}`,
      "",
      `- **Lawful basis:** ${lawfulBasisForPurpose[purpose]}`,
      `- **Retention:** ${[...row.retentions].sort().join(", ")}`,
      `- **Tables:** ${[...row.tables]
        .sort()
        .map((t) => `\`${t}\``)
        .join(", ")}`,
      "- **Categories of personal data:**",
      "",
    );
    for (const category of [...row.categories].sort()) {
      lines.push(`  - ${category}`);
    }
    lines.push("");
  }

  return `${lines.join("\n").trimEnd()}\n`;
}
